test('Athom C3 target preserves Steve main exact compiled hardware contract', () => {
  const contract = loadContract();
  const target = contract.targets.find(item => item.id === 'athom-c3-tubes');
  assert.ok(target);
  assert.deepEqual(target.compiledProfile, {
    environment: 'esp32-c3-athom_tubes',
    releaseIdentity: 'ESP32-C3_ATHOM_TUBES',
    ledPin: 10,
    buttonPin: 9,
    ledCount: 150
  });
  assert.equal(target.chipFamily, 'ESP32-C3');
  assert.equal(target.board, 'esp32-c3-devkitm-1');
  assert.equal(target.flashMode, 'dio');
  assert.equal(target.flashSizeBytes, 4194304);
  assert.deepEqual(target.partition.otaSlots, [
    {id: 'ota_0', offset: 65536, sizeBytes: 1572864},
    {id: 'ota_1', offset: 1638400, sizeBytes: 1572864}
  ]);

  const artifacts = contract.artifacts.filter(item => item.targetId === target.id);
  assert.deepEqual(artifacts.map(item => item.transport).sort(), ['ota', 'usb']);
  assert.ok(artifacts.every(item => item.releaseIdentity === target.compiledProfile.releaseIdentity));
  assert.ok(artifacts.every(item => item.buildSourceState.includes('generated C3 contract projection')));
  assert.ok(artifacts.every(item => item.lengthBytes <= target.flashSizeBytes));
  const header = fs.readFileSync(cppOutputPath, 'utf8');
  assert.match(header, /CANONICAL_TARGET_ATHOM_C3_TUBES[\s\S]*CanonicalTargetAthomC3Tubes, 2, 1,/);
});

test('Waveshare S3 target is a flash-only compiled hardware contract', () => {
  const contract = loadContract();
  const target = contract.targets.find(item => item.id === 'waveshare-s3-tubes-remote');
  assert.ok(target);
  assert.deepEqual(target.compiledProfile, {
    environment: 'waveshare_s3_tubes_target',
    releaseIdentity: 'WAVESHARE_S3_TUBES_TARGET'
  });
  assert.equal(target.chipFamily, 'ESP32-S3');
  assert.equal(target.board, 'esp32-s3-devkitc-1');
  assert.equal(target.flashMode, 'qio');
  assert.equal(target.flashSizeBytes, 16777216);
  assert.deepEqual(target.partition.otaSlots, [
    {id: 'ota_0', offset: 65536, sizeBytes: 6291456},
    {id: 'ota_1', offset: 6356992, sizeBytes: 6291456}
  ]);

  const artifacts = contract.artifacts.filter(item => item.targetId === target.id);
  assert.deepEqual(artifacts.map(item => item.transport).sort(), ['ota', 'usb']);
  assert.ok(artifacts.every(item => item.releaseIdentity === target.compiledProfile.releaseIdentity));
  assert.ok(artifacts.every(item => item.lengthBytes <= target.flashSizeBytes));
  assert.ok(artifacts.find(item => item.transport === 'ota').lengthBytes <= target.partition.otaSlots[0].sizeBytes);
  const header = fs.readFileSync(cppOutputPath, 'utf8');
  assert.match(header, /CANONICAL_TARGET_WAVESHARE_S3_TUBES_REMOTE[\s\S]*CanonicalTargetWaveshareS3TubesRemote, 3, 2,/);
});

// Resolve the composed PlatformIO configuration when the optional firmware
// toolchain is installed; Node-only environments still exercise the contract.
test('Waveshare S3 effective build preserves exact flash and USB identity', {
  skip: pioAvailable ? false : 'PlatformIO is not installed'
}, () => {
  const output = execFileSync('pio', ['project', 'config', '--json-output'], {
    cwd: root,
    encoding: 'utf8'
  });
  const sections = new Map(JSON.parse(output).map(([name, options]) => [name, Object.fromEntries(options)]));
  const environment = sections.get('env:waveshare_s3_tubes_target');
  assert.ok(environment);
  assert.equal(environment.board, 'esp32-s3-devkitc-1');
  assert.equal(environment['board_build.flash_mode'], 'qio');
  assert.equal(environment['board_upload.flash_size'], '16MB');
  assert.equal(environment['board_upload.maximum_size'], '16777216');
  assert.equal(environment['board_build.arduino.memory_type'], 'qio_opi');
  assert.equal(environment['board_build.partitions'], 'contracts/update/partitions/WLED_ESP32S3_WAVESHARE_16MB.csv');
  const flags = [].concat(environment.build_flags).join(' ');
  assert.match(flags, /WLED_RELEASE_NAME=\\\"WAVESHARE_S3_TUBES_TARGET\\\"/);
  assert.equal((flags.match(/ARDUINO_USB_CDC_ON_BOOT=1/g) || []).length, 1);
  for (const excluded of ['WaveshareS3CompileCanary', 'TUBES_NULL_OUTPUT', 'TUBES_READ_ONLY_FIELD_SHELL'])
    assert.doesNotMatch(flags + ' ' + environment.custom_usermods, new RegExp(excluded));
});

test('duplicate and unknown identities fail closed', () => {
  const canonical = loadContract();
  const duplicateTarget = clone(canonical);
  duplicateTarget.targets.push(clone(duplicateTarget.targets[0]));
  assert.match(validateContract(duplicateTarget, {checkFiles: false}).join('\n'), /duplicate target id/);

  const duplicateArtifact = clone(canonical);
  duplicateArtifact.artifacts.push(clone(duplicateArtifact.artifacts[0]));
  assert.match(validateContract(duplicateArtifact, {checkFiles: false}).join('\n'), /duplicate artifact id/);

  const unknownTarget = clone(canonical);
  unknownTarget.artifacts[0].targetId = 'unknown-target';
  assert.match(validateContract(unknownTarget, {checkFiles: false}).join('\n'), /unknown targetId/);

  const unknownClass = clone(canonical);
  unknownClass.artifacts[0].releaseClass = 'Unknown';
  assert.match(validateContract(unknownClass, {checkFiles: false}).join('\n'), /unknown releaseClass/);

  const missingIdentity = clone(canonical);
  delete missingIdentity.artifacts[0].releaseIdentity;
  assert.match(validateContract(missingIdentity, {checkFiles: false}).join('\n'), /missing releaseIdentity/);
});

test('numeric discriminators are unique, ranged, and state values are frozen', () => {
  for (const key of ['releaseClasses', 'targets', 'artifacts', 'updateStates']) {
    const contract = loadContract();
    contract[key][1].cppValue = contract[key][0].cppValue;
    assert.match(validateContract(contract, {checkFiles: false}).join('\n'), /duplicate .* cppValue/);
    contract[key][1].cppValue = 256;
    assert.match(validateContract(contract, {checkFiles: false}).join('\n'), /invalid cppValue/);
  }
  const changedState = loadContract();
  changedState.updateStates.find(item => item.id === 'Complete').cppValue = 7;
  assert.match(validateContract(changedState, {checkFiles: false}).join('\n'), /must preserve cppValue 5/);
});

test('partition CSV parser and semantic geometry fail closed', () => {
  const contract = loadContract();
  for (const target of contract.targets) {
    const rows = parsePartitionCsv(fs.readFileSync(path.join(root, target.partition.csvPath), 'utf8'));
    const errors = [];
    validatePartitionRows(errors, target, rows);
    assert.deepEqual(errors, []);
    assert.equal(rows.filter(row => row.type === 'app' && row.subtype.startsWith('ota_')).length, 2);
  }
  assert.throws(() => parsePartitionCsv('bad,app,ota_0,0x10000,wat,'), /invalid offset or size/);
  assert.throws(() => parsePartitionCsv('bad,app,ota_0,0x10000,0x10000'), /6 columns/);
  assert.throws(() => parsePartitionCsv('bad,garbage,ota_0,0x10000,0x10000,'), /unsupported tokens/);
  assert.throws(() => parsePartitionCsv('bad,app,ota 0,0x10000,0x10000,'), /unsupported tokens/);
  assert.throws(() => parsePartitionCsv('bad,app,ota_0,0x10000,0x10000,encrypted'), /unsupported tokens/);
  const target = contract.targets[0];
  const rows = parsePartitionCsv(fs.readFileSync(path.join(root, target.partition.csvPath), 'utf8'));
  rows.find(row => row.subtype === 'ota_1').offset += 0x10000;
  const errors = [];
  validatePartitionRows(errors, target, rows);
  assert.match(errors.join('\n'), /geometry does not match|rows overlap/);
});

