test('artifact vocabularies, combinations, identities, and bounds are closed', () => {
  const cases = [
    ['kind', 'mystery', /unsupported kind/],
    ['transport', 'wifi', /unsupported transport/],
    ['transport', 'usb', /application image must use OTA/],
    ['writeOffset', 0, /OTA application must not have writeOffset/],
    ['buildOffset', -1, /invalid buildOffset/],
    ['buildCommit', '02abdd5d', /invalid buildCommit/],
    ['lengthBytes', 99999999, /exceeds every OTA slot/],
  ];
  for (const [field, value, pattern] of cases) {
    const contract = loadContract();
    Object.assign(contract.artifacts[1], {[field]: value});
    assert.match(validateContract(contract, {checkFiles: false}).join('\n'), pattern);
  }
  const merged = loadContract();
  merged.artifacts[0].components[0].sha256 = 'bad';
  assert.match(validateContract(merged, {checkFiles: false}).join('\n'), /invalid sha256/);
  const mergedOffset = loadContract();
  mergedOffset.artifacts[0].writeOffset = 65536;
  assert.match(validateContract(mergedOffset, {checkFiles: false}).join('\n'), /writeOffset must be 0/);
  const duplicate = loadContract();
  duplicate.artifacts[0].components[1].id = duplicate.artifacts[0].components[0].id;
  assert.match(validateContract(duplicate, {checkFiles: false}).join('\n'), /duplicate .* component id/);
});

// A merged image and its OTA artifact represent one build, so their application
// bytes must remain identical even when both individual files are internally valid.
test('merged and OTA artifacts from one build share exact application bytes', () => {
  const mismatchedApplication = loadContract();
  mismatchedApplication.artifacts.find(item => item.id === 'waveshare-s3-v14-ota-application').sha256 = '0'.repeat(64);
  assert.match(validateContract(mismatchedApplication, {checkFiles: false}).join('\n'),
    /merged.*application does not match/i);

  const missingOtaPair = loadContract();
  missingOtaPair.artifacts.find(item => item.id === 'waveshare-s3-v14-ota-application').buildSourceState += ' mismatch';
  assert.match(validateContract(missingOtaPair, {checkFiles: false}).join('\n'),
    /missing matching OTA application/);
});

